"""Depth-Domination Decision Procedure with Certificate Extraction.

Decides whether the ladder theory L(c, N) is a weakening of L(c', N) -- i.e. whether
every theorem of the second is a theorem of the first -- and returns, in either case, an
explicit certificate:

  * on acceptance, the unique cut level D with  d_c = min(D, d_c')  pointwise;
  * on rejection, a single formula provable in L(c', N) and refuted in L(c, N),
    together with the world of the c-model at which it fails.

Here d_c(i) = min(N, c(i)) is the depth vector.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple, Union

Formula = tuple
BOT: Formula = ("bot",)


def imp(a: Formula, b: Formula) -> Formula:
    return ("imp", a, b)


def box(i: int, a: Formula) -> Formula:
    return ("box", i, a)


def neg(a: Formula) -> Formula:
    return imp(a, BOT)


def box_pow(i: int, k: int, a: Formula) -> Formula:
    out = a
    for _ in range(k):
        out = box(i, out)
    return out


def show(a: Formula) -> str:
    if a[0] == "bot":
        return "_|_"
    if a[0] == "atom":
        return f"p{a[1]}"
    if a[0] == "imp":
        return f"~{show(a[1])}" if a[2] == BOT else f"({show(a[1])} -> {show(a[2])})"
    return f"[{a[1]}]{show(a[2])}"


def sat_ladder(c: Sequence[int], m: int, a: Formula) -> bool:
    """Truth at world m of the tag-sensitive ladder model: box_i is vacuous above c(i)."""
    if a[0] == "bot":
        return False
    if a[0] == "atom":
        return True
    if a[0] == "imp":
        return (not sat_ladder(c, m, a[1])) or sat_ladder(c, m, a[2])
    i = a[1]
    if m > c[i]:
        return True
    return all(sat_ladder(c, n, a[2]) for n in range(m))


def order_witness(i: int, j: int, m: int) -> Formula:
    """box_i bot -> (~box_j^m bot -> ~box_j^{m+1} bot)."""
    return imp(box(i, BOT), imp(neg(box_pow(j, m, BOT)), neg(box_pow(j, m + 1, BOT))))


def decide_inclusion(
    c: Sequence[int], cp: Sequence[int], N: int
) -> Dict[str, Union[bool, int, str, None]]:
    """Decide Incl(c, c', N) and return a certificate.

    Complexity: O(T) arithmetic operations on T tags (two linear scans and one maximum).
    The certificate formula, when produced, has size O(N).
    """
    d = [min(N, x) for x in c]
    dp = [min(N, x) for x in cp]

    # Step 1 -- depths may only increase.
    for i, (di, dpi) in enumerate(zip(d, dp)):
        if di > dpi:
            f = box_pow(i, dpi + 1, BOT)
            return {
                "included": False,
                "reason": f"depth of tag {i} decreases: {di} -> {dpi}",
                "certificate": show(f),
                "failing_world": None,
            }

    # Step 2 -- a depth may increase strictly only at a tag of maximal depth.
    top = max(d)
    for i, (di, dpi) in enumerate(zip(d, dp)):
        if di < dpi and di < top:
            j = max(range(len(d)), key=lambda k: d[k])  # a strictly deeper tag
            m = di + 1
            f = order_witness(i, j, m)
            return {
                "included": False,
                "reason": (
                    f"depth of tag {i} rises {di} -> {dpi} although tag {j} is deeper "
                    f"({d[j]})"
                ),
                "certificate": show(f),
                "failing_world": m,
            }

    # Step 3 -- accept, and read off the cut level.
    return {
        "included": True,
        "reason": "depth domination holds",
        "certificate": None,
        "cut_level": top,
    }


def verify(c: Sequence[int], cp: Sequence[int], N: int) -> None:
    """Print the decision together with a direct check of the certificate."""
    out = decide_inclusion(c, cp, N)
    print(f"c = {tuple(c)}, c' = {tuple(cp)}, N = {N}")
    print(f"  depth vectors: {[min(N, x) for x in c]} -> {[min(N, x) for x in cp]}")
    print(f"  included: {out['included']}  ({out['reason']})")
    if out["included"]:
        D = out["cut_level"]
        ok = all(min(N, c[i]) == min(D, min(N, cp[i])) for i in range(len(c)))
        print(f"  cut level D = {D};  d_c = min(D, d_c') pointwise: {ok}")
    else:
        print(f"  separating formula: {out['certificate']}")
        if out["failing_world"] is not None:
            m = out["failing_world"]
            i = int(out["reason"].split()[3])
            print(f"  it fails at world {m} of the c-model (tag {i} is dead there)")


if __name__ == "__main__":
    verify((0, 1, 1), (1, 2, 2), 2)   # the counterexample to the old conjecture
    print()
    verify((1, 1, 1), (1, 2, 3), 3)   # a genuine truncation, cut level 1
    print()
    verify((2, 1), (1, 1), 2)         # a decreasing depth

"""Realization of a Prescribed (Inconsistency Height, Reflection Depth) Pair.

Given a target inconsistency height n and a target reflection depth d, construct a
consistent theory of the logic of provability whose provable iterated boxed falsa are
exactly the box_i^k bot with k > n, and whose depth-restricted reflection rule holds
exactly up to depth d.  The construction succeeds if and only if d <= n.

The witness is the block theory B(n, w) with shift point w = n - d: the ladder with
worlds 0..n, tag-blind accessibility n -> {0,...,n-1}, and every atom true exactly at
the worlds below w.  Its reflection depth is n - w = d, because a formula of box depth
k can look down at most k rungs and therefore cannot distinguish the top world n from
the world n-1 once both lie at height at least w + k.

The failure of reflection one step higher is certified by the depth probe
box_i^d p0, of box depth exactly d: the theory proves its box and refutes it.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple, Union

Formula = tuple
BOT: Formula = ("bot",)


def atom(p: int) -> Formula:
    return ("atom", p)


def imp(a: Formula, b: Formula) -> Formula:
    return ("imp", a, b)


def box(i: int, a: Formula) -> Formula:
    return ("box", i, a)


def box_pow(i: int, k: int, a: Formula) -> Formula:
    out = a
    for _ in range(k):
        out = box(i, out)
    return out


def show(a: Formula) -> str:
    if a[0] == "bot":
        return "_|_"
    if a[0] == "atom":
        return f"p{a[1]}"
    if a[0] == "imp":
        return f"~{show(a[1])}" if a[2] == BOT else f"({show(a[1])} -> {show(a[2])})"
    return f"[{a[1]}]{show(a[2])}"


def box_depth(a: Formula) -> int:
    if a[0] in ("bot", "atom"):
        return 0
    if a[0] == "imp":
        return max(box_depth(a[1]), box_depth(a[2]))
    return 1 + box_depth(a[2])


def sat_block(w: int, m: int, a: Formula) -> bool:
    """Truth at world m under the block valuation with shift point w."""
    if a[0] == "bot":
        return False
    if a[0] == "atom":
        return m < w
    if a[0] == "imp":
        return (not sat_block(w, m, a[1])) or sat_block(w, m, a[2])
    return all(sat_block(w, n, a[2]) for n in range(m))


def provable_block(n: int, w: int, a: Formula) -> bool:
    """a is a theorem of B(n, w): true at every world 0..n."""
    return all(sat_block(w, m, a) for m in range(n + 1))


def realize(n: int, d: int) -> Optional[Dict[str, Union[int, str, List[int]]]]:
    """Return the parameters of a theory of height n and reflection depth exactly d.

    Returns None when d > n, which is exactly the unrealizable case: the sentence
    box_i^n bot has box depth n and its box is box_i^{n+1} bot, so any theory of height
    n already violates the depth-(n+1) rule.

    Complexity: O(1) to produce the parameters; O(n) to write down the certificates.
    """
    if d > n:
        return None
    w = n - d
    return {
        "height": n,
        "shift_point": w,
        "reflection_depth": d,
        "worlds": list(range(n + 1)),
        "atoms_true_at": list(range(min(w, n + 1))),
        "reflection_certificate": show(box_pow(0, d, atom(0))),
        "height_certificate": show(box_pow(0, n + 1, BOT)),
    }


def check(n: int, d: int) -> None:
    """Realize the pair (n, d) and verify both invariants directly."""
    spec = realize(n, d)
    if spec is None:
        print(f"(n, d) = ({n}, {d}): unrealizable (d > n)")
        return
    w = spec["shift_point"]
    height_ok = all(provable_block(n, w, box_pow(0, k, BOT)) == (k > n) for k in range(n + 4))
    probe = box_pow(0, d, atom(0))
    reflect_fails = provable_block(n, w, box(0, probe)) and not provable_block(n, w, probe)
    print(f"(n, d) = ({n}, {d}) -> B({n},{w})")
    print(f"   atoms true at worlds {spec['atoms_true_at']}, model has worlds 0..{n}")
    print(f"   inconsistency height is exactly {n}: {height_ok}")
    print(f"   depth-{d + 1} reflection fails, witnessed by {show(probe)} "
          f"(box depth {box_depth(probe)}): {reflect_fails}")


if __name__ == "__main__":
    for n in range(4):
        for d in range(n + 2):
            check(n, d)

